/* ORIGINAL FILE: assets/styles/sources/system/loader.css. Keep order from index.html. */
.vatra-loading-screen{
  position:fixed;
  inset:0;
  z-index:9998;
  display:grid;
  place-items:center;
  isolation:isolate;
  box-sizing:border-box;
  min-height:100svh;
  padding:24px;
  overflow:hidden;
  background:
    radial-gradient(ellipse 52% 50% at 50% 43%,rgba(229,239,255,.92) 0%,rgba(229,239,255,0) 82%),
    #f7f9fd;
  color:#1a2e49;
  font-family:"VATRA Onest",Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",system-ui,sans-serif;
  -webkit-backdrop-filter:none;
  backdrop-filter:none;
  opacity:1;
  visibility:visible;
  transition:opacity .25s ease,visibility .25s ease;
}
.vatra-loading-screen *{box-sizing:border-box}
.vatra-loading-screen::before{
  content:"";
  position:absolute;
  width:min(92vw,690px);
  aspect-ratio:1;
  left:50%;
  top:50%;
  transform:translate(-50%,-50%);
  border-radius:50%;
  border:1px solid rgba(7,87,245,.045);
  box-shadow:0 0 0 90px rgba(7,87,245,.014),0 0 0 185px rgba(7,87,245,.009);
  pointer-events:none;
}
.vatra-loading-screen .vatra-loading-card{
  position:relative;
  z-index:1;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  width:min(100%,388px);
  margin:0;
  padding:38px 38px 33px;
  border:1px solid #e2eaf5;
  border-radius:23px;
  background:rgba(255,255,255,.97);
  box-shadow:0 24px 65px rgba(24,58,105,.065),0 5px 20px rgba(24,58,105,.03);
  text-align:center;
  animation:vatra-loader-appear .4s ease-out both;
}
.vatra-loading-screen .vatra-loading-card::before{
  content:"";
  position:absolute;
  height:3px;
  left:34%;
  right:34%;
  top:0;
  border-radius:0 0 99px 99px;
  background:linear-gradient(90deg,#1266ff,#0757f5,#20a0fa);
}
.vatra-loading-screen .vatra-loading-brand{
  display:flex;
  justify-content:center;
  align-items:center;
  width:100%;
  margin:0 0 28px;
  padding:0;
  min-height:34px;
}
.vatra-loading-screen .vatra-loading-wordmark-image{
  display:block;
  width:175px;
  height:auto;
  object-fit:contain;
  object-position:center;
  filter:none;
}
.vatra-loading-screen .vatra-loading-kicker{
  margin:0 0 12px;
  color:#0757f5;
  font-size:10px;
  line-height:1.4;
  font-weight:750;
  letter-spacing:.14em;
  text-transform:uppercase;
}
.vatra-loading-screen .vatra-loading-heading{
  margin:0;
  padding:0;
  color:#162b46;
  font-family:inherit;
  font-size:22px;
  line-height:1.3;
  font-weight:750;
  letter-spacing:-.034em;
}
.vatra-loading-screen .vatra-loading-subtitle{
  max-width:290px;
  margin:10px 0 27px;
  color:#7d8ca3;
  font-family:inherit;
  font-size:13px;
  font-weight:450;
  line-height:1.65;
}
.vatra-loading-screen .vatra-loading-track{
  position:relative;
  display:block;
  width:100%;
  max-width:244px;
  height:4px;
  margin:0;
  overflow:hidden;
  border-radius:100px;
  background:#e9eff9;
}
.vatra-loading-screen .vatra-loading-track span{
  position:absolute;
  inset:0 auto 0 0;
  display:block;
  width:42%;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg,#0757f5,#248dff);
  animation:vatra-loader-bar 1.45s cubic-bezier(.42,0,.58,1) infinite;
}
.vatra-loading-screen .vatra-loading-status{
  display:flex;
  justify-content:center;
  align-items:center;
  gap:8px;
  margin:14px 0 0;
  color:#7b8da8;
  font-family:inherit;
  font-size:11px;
  line-height:1.5;
  font-weight:600;
}
.vatra-loading-screen .vatra-loading-status::before{
  content:"";
  width:6px;
  height:6px;
  border-radius:50%;
  background:#1683fa;
  box-shadow:0 0 0 4px rgba(7,87,245,.09);
  animation:vatra-loader-dot 1.5s ease-in-out infinite;
}
.vatra-loading-screen .vatra-loading-footnote{
  position:absolute;
  bottom:max(22px,env(safe-area-inset-bottom));
  left:0;
  right:0;
  padding:0 14px;
  color:#9ba9bb;
  text-align:center;
  font:600 10px/1.5 "VATRA Onest",Inter,system-ui,sans-serif;
  letter-spacing:.105em;
  text-transform:uppercase;
}
.vatra-loading-screen.vatra-loading--leaving{
  opacity:0;
  visibility:hidden;
  pointer-events:none;
}
@keyframes vatra-loader-bar{
  0%{transform:translateX(-108%);}
  55%{transform:translateX(110%);}
  100%{transform:translateX(255%);}
}
@keyframes vatra-loader-dot{
  0%,100%{opacity:.6;}
  50%{opacity:1;}
}
@keyframes vatra-loader-appear{
  from{opacity:0;transform:translateY(8px);}
  to{opacity:1;transform:translateY(0);}
}
@media(max-width:480px){
  .vatra-loading-screen{padding:18px;background:#f7f9fd;}
  .vatra-loading-screen .vatra-loading-card{width:min(100%,360px);padding:33px 23px 29px;border-radius:20px;}
  .vatra-loading-screen .vatra-loading-wordmark-image{width:155px;}
  .vatra-loading-screen .vatra-loading-brand{margin-bottom:24px;}
  .vatra-loading-screen .vatra-loading-heading{font-size:20px;}
  .vatra-loading-screen .vatra-loading-footnote{font-size:9px;}
}
@media(prefers-reduced-motion:reduce){
  .vatra-loading-screen,.vatra-loading-screen .vatra-loading-card,.vatra-loading-screen .vatra-loading-track span,.vatra-loading-screen .vatra-loading-status::before{animation:none!important;transition:none!important;}
  .vatra-loading-screen .vatra-loading-track span{width:55%;transform:none;}
}


