:root{--v-blue:#0759f7;--v-blue-hover:#064bd0;--v-ink:#172438;--v-muted:#68778b;--v-border:#e0e6ef;--v-canvas:#f5f7fb;--v-card:#fff;--v-soft:#eef3fb}
*{box-sizing:border-box}
html,body{margin:0;min-height:100%;background:var(--v-canvas);color:var(--v-ink)}
body{font-family:var(--vatra-ui-font),-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:14px;line-height:1.5}
.layout{width:min(1320px,100%);max-width:1320px;margin:0 auto;padding:0 24px;display:grid;grid-template-columns:220px minmax(0,680px) 280px;gap:24px;align-items:start}
.sidebar{position:sticky;top:0;height:100dvh;min-width:0;padding:28px 0 18px;display:flex;flex-direction:column;background:transparent;border:0}
.brand{display:flex;align-items:center;gap:11px;margin:0 0 30px 8px;color:var(--v-ink);font-size:22px;line-height:1.1;font-weight:800;letter-spacing:-.8px;text-decoration:none}
.brand small{display:block;margin-top:5px;font-size:9px;letter-spacing:1.15px;font-weight:750;color:#8996a9}
.brand-icon,.welcome-mark{display:grid;place-items:center;flex:0 0 auto;width:38px;height:38px;border-radius:12px;background:var(--v-blue);color:#fff;font-size:23px;font-weight:800;box-shadow:0 5px 12px #0759f71c}
.sidebar nav{display:grid;gap:5px}
.sidebar .nav{display:flex;align-items:center;gap:12px;width:100%;min-height:45px;margin:0;padding:0 13px;border:0;border-radius:10px;background:transparent;color:#56657a;text-align:left;font-size:13px;font-weight:650}
.sidebar .nav:hover{background:#e9eef6;color:var(--v-ink)}
.sidebar .nav-icon{width:20px;text-align:center;font-size:17px}
.primary,.create-button{border:0;background:var(--v-blue);color:#fff;border-radius:10px;font-weight:700;box-shadow:none}
.primary:hover,.create-button:hover{background:var(--v-blue-hover)}
.sidebar .wide{width:100%;min-height:45px;margin-top:18px}
.sidebar-bottom{display:flex;gap:10px;align-items:flex-start;margin-top:auto;padding:17px 9px 0;border-top:1px solid var(--v-border);color:#66758a;font-size:12px}
.sidebar-bottom small{display:block;margin-top:4px;color:#8793a5;font-size:11px}
.sidebar-spark{color:var(--v-blue);font-size:17px}
.main{min-width:0;width:100%;max-width:none;min-height:100dvh;margin:0;padding:20px 0 60px;background:transparent;border:0}
.topbar{position:relative;top:auto;z-index:5;display:flex;align-items:center;gap:10px;width:100%;height:58px;margin:0 0 16px;padding:8px 10px;border:1px solid var(--v-border);border-radius:13px;background:#fff;box-shadow:0 2px 8px #15294a05}
.mobile-brand{display:none}
.search{display:flex;align-items:center;gap:9px;flex:1;min-width:0;height:40px;padding:0 12px;border:1px solid transparent;border-radius:9px;background:#f1f4f8;color:#8491a3}
.search input{width:100%;min-width:0;border:0;outline:0;background:transparent;color:var(--v-ink);font:inherit;font-size:13px}
.search:focus-within{border-color:#a8c3ff;background:#fff;box-shadow:0 0 0 3px #0759f712}
.pill{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:36px;padding:0 13px;border:1px solid var(--v-border);border-radius:9px;background:#fff;color:#42536a;font-size:12px;font-weight:650;white-space:nowrap}
.pill:hover{background:#f7f9fc;border-color:#cbd6e6}
.avatar{display:grid;place-items:center;flex:0 0 auto;width:38px;height:38px;border:0;border-radius:50%;background:linear-gradient(145deg,#68a2ff,#3475f5);color:#fff;font-size:12px;font-weight:750;box-shadow:none}
.heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 14px;padding:22px 22px 20px;border:1px solid var(--v-border);border-radius:14px;background:#fff}
.heading>div{min-width:0}
.heading .eyebrow{margin:0 0 5px;color:var(--v-blue);font-size:10px;line-height:1.3;letter-spacing:1.3px;font-weight:800}
.heading h1{margin:0;color:var(--v-ink);font-size:29px;line-height:1.2;letter-spacing:-1px;font-weight:800}
.heading p:last-child{margin:7px 0 0;color:var(--v-muted);font-size:13px;line-height:1.5}
.heading .pill{align-self:center;flex:0 0 auto}
.quick-compose{margin:0 0 14px;padding:16px 18px 12px;border:1px solid var(--v-border);border-radius:14px;background:#fff;box-shadow:0 2px 8px #15294a05}
.compose-row{display:flex;align-items:center;gap:11px}
.prompt{flex:1;min-width:0;min-height:44px;padding:0 15px;border:1px solid transparent;border-radius:11px;background:#f1f4f8;color:#738197;text-align:left;font:inherit;font-size:13px}
.prompt:hover{border-color:#d5e2f8;background:#f7f9fc}
.compose-tools{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:13px;padding-top:12px;border-top:1px solid #edf0f5}
.compose-tools button{min-height:34px;padding:0 10px;border:0;border-radius:8px;background:transparent;color:#65758b;font-size:12px;font-weight:650}
.compose-tools button:hover{background:#f1f5fb;color:var(--v-blue)}
.compose-tools .post-now{margin-left:auto;padding:0 14px;background:#e8efff;color:var(--v-blue)}
.compose-tools .post-now:hover{background:#dce8ff}
.feed{display:grid;gap:12px;min-width:0}
