html{scroll-behavior:smooth}
body{min-width:320px;overflow-x:clip}
img,video,canvas,svg{max-width:100%}
button,a,label[for]{-webkit-tap-highlight-color:transparent}
button,input,select,textarea{font:inherit}
button,a,[role="button"],summary,label[for]{
  transition:background-color .18s ease,border-color .18s ease,color .18s ease,box-shadow .18s ease,transform .18s cubic-bezier(.2,.8,.2,1),opacity .18s ease;
}
button:not(:disabled){cursor:pointer}
button:active:not(:disabled),[role="button"]:active{transform:scale(.975)}
button:disabled{cursor:not-allowed;opacity:.58}
:where(button,a,input,select,textarea,[tabindex]):focus-visible{
  outline:3px solid rgba(7,87,245,.3);
  outline-offset:3px;
}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation-duration:.01ms!important;animation-iteration-count:1!important}
}


